"""A queue of videos to publish later.

A job is one finished video file with the title, description, tags and places the person settled on, plus the local time to send it. The queue is
`schedule.json` in the workspace. `run_due` publishes what is due through `settings.publish_file` (the same route as "Publish now", so a video is
never sent twice to the same place); `start_background` checks once a minute while the browser app is open. Nothing is sent when the app is
closed: a job whose time passed is sent the next time the app runs. The video and its title leave this PC when a job is sent.
"""
import json
import os
import re
import threading
import time
import uuid
from datetime import datetime, timedelta, timezone

def pakistan_now():
    """Schedule wall times are Pakistan time regardless of the Windows timezone."""
    return datetime.now(timezone.utc).astimezone(timezone(timedelta(hours=5))).replace(tzinfo=None)


FILE = "schedule.json"
LOCK = threading.Lock()


def _path(home):
    return os.path.join(home, FILE)


def _load(home):
    try:
        with open(_path(home), encoding="utf-8") as f:
            data = json.load(f)
        return [j for j in data if isinstance(j, dict)] if isinstance(data, list) else []
    except (OSError, ValueError):
        return []


def _save(home, jobs):
    tmp = _path(home) + ".tmp"
    with open(tmp, "w", encoding="utf-8", newline="\n") as f:
        json.dump(jobs, f, indent=1)
    os.replace(tmp, _path(home))


def parse_when(text, now=None):
    """A time the person typed -> datetime, or None. Accepts `2026-11-22 09:00`, `09:00` (today, or tomorrow when it has passed), `in 30m`, `in 2h`, `in 1d`."""
    now = now or pakistan_now()
    s = " ".join(str(text or "").lower().split())
    m = re.fullmatch(r"(?:in |\+)\s*(\d+)\s*(m|min|h|hr|d)", s)
    if m:
        n, unit = int(m.group(1)), m.group(2)
        return now + (timedelta(minutes=n) if unit.startswith("m") else timedelta(hours=n) if unit in ("h", "hr") else timedelta(days=n))
    for fmt in ("%Y-%m-%d %H:%M", "%Y-%m-%d %H:%M:%S", "%Y-%m-%dt%H:%M", "%Y-%m-%d %H.%M"):
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            pass
    m = re.fullmatch(r"(\d{1,2})[:.](\d{2})", s)
    if m and int(m.group(1)) < 24 and int(m.group(2)) < 60:
        t = now.replace(hour=int(m.group(1)), minute=int(m.group(2)), second=0, microsecond=0)
        return t if t > now else t + timedelta(days=1)
    return None


def add(home, path, when, title, description, tags, platforms, privacy="private", account="1", now=None):
    """Queue one video. Returns (ok, message, job)."""
    from shortsflow import settings
    at = parse_when(when, now)
    if at is None:
        return False, "I could not read that time. Use `2026-11-22 09:00`, `09:00` or `in 2h`.", None
    if at <= (now or pakistan_now()):
        return False, "That time has already passed. Pick a later one, or use Publish now.", None
    platforms = [p for p in (platforms or []) if p in settings.valid_platforms()]
    if not platforms:
        return False, "Tick at least one place to publish to.", None
    if not os.path.isfile(path):
        return False, "That video file is no longer there.", None
    job = {"id": uuid.uuid4().hex[:8], "path": os.path.abspath(path), "title": " ".join(str(title or "").split())[:200], "description": str(description or ""),
           "tags": str(tags or ""), "platforms": platforms, "privacy": privacy if privacy in settings.PRIVACY else "private",
           "account": settings.clean_account(account), "at": at.strftime("%Y-%m-%d %H:%M"), "status": "pending", "result": ""}
    with LOCK:
        jobs = _load(home)
        jobs.append(job)
        _save(home, jobs)
    return True, f"Scheduled for {job['at']}: {os.path.basename(path)} -> {', '.join(platforms)}. The app must be open at that time (a missed one is sent when it next runs).", job


def jobs(home, status=None):
    out = _load(home)
    out = [j for j in out if status is None or j.get("status") == status]
    return sorted(out, key=lambda j: j.get("at", ""))


def cancel(home, job_id):
    with LOCK:
        data = _load(home)
        for j in data:
            if j.get("id") == job_id and j.get("status") == "pending":
                j["status"] = "cancelled"
                _save(home, data)
                return True
    return False


def due(home, now=None):
    now = (now or pakistan_now()).strftime("%Y-%m-%d %H:%M")
    return [j for j in jobs(home, "pending") if j.get("at", "9999") <= now]


def run_due(home, env_path=None, now=None, publish=None, environ=None):
    """Send every pending job whose time has come. Returns [(job id, ok, text)]. A failed job is marked failed and not retried by itself."""
    from shortsflow import settings
    publish = publish or settings.publish_file
    results = []
    for job in due(home, now):
        try:
            ok, lines = publish(job["path"], job["title"], job["description"], job["tags"], job["platforms"], privacy=job["privacy"],
                                account=job["account"], home=home, env_path=env_path, environ=environ)
            text = " ".join(lines)[:500]
        except Exception as e:                      # one broken job must not stop the loop
            ok, text = False, f"{type(e).__name__}: {e}"[:500]
        with LOCK:
            data = _load(home)
            for j in data:
                if j.get("id") == job["id"]:
                    j["status"], j["result"] = ("done" if ok else "failed"), text
            _save(home, data)
        results.append((job["id"], ok, text))
    return results


def markdown(home):
    """The queue as a small table for the page."""
    rows = jobs(home)
    if not rows:
        return "Nothing is scheduled."
    icon = {"pending": "⏳", "done": "✅", "failed": "❌", "cancelled": "🚫"}
    lines = ["| id | when | video | to | state |", "|---|---|---|---|---|"]
    for j in rows[-20:]:
        state = icon.get(j["status"], "") + " " + j["status"] + (f": {j['result']}" if j["status"] == "failed" and j.get("result") else "")
        lines.append(f"| `{j['id']}` | {j['at']} | {os.path.basename(j['path'])} | {', '.join(j['platforms'])} | {state.replace('|', '/')} |")
    return "\n".join(lines)


def start_background(home, env_path=None, interval=60):
    """Check the queue every `interval` seconds on a daemon thread (the browser app calls this once). Returns the thread."""
    def loop():
        while True:
            try:
                run_due(home, env_path)
            except Exception:
                pass
            time.sleep(interval)
    t = threading.Thread(target=loop, name="shortsflow-schedule", daemon=True)
    t.start()
    return t
